'use strict';

// The rules reference (v2.161.0, docs/ttrpg/README.md phase 6): the SRD data
// generated by tools/build-srd.mjs. Every set is there for both editions, every
// entry has what the screens use, and every dice string in it is one the
// server's roller takes, so a roll button from the SRD never fails.

const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const srd = path.resolve(__dirname, '../client/src/srd');
const load = (edition, kind) => JSON.parse(fs.readFileSync(path.join(srd, edition, `${kind}.json`), 'utf8'));
const dice = () => import('../server/lib/dice.js');

test('both editions have every set, at the sizes the SRDs have', () => {
  const min = { spells: 300, monsters: 300, equipment: 150, 'magic-items': 200, conditions: 14 };
  for (const edition of ['2014', '2024']) {
    for (const [kind, n] of Object.entries(min)) {
      const list = load(edition, kind);
      assert.ok(list.length >= n, `${edition} ${kind}: ${list.length}`);
      assert.equal(new Set(list.map(x => x.id)).size, list.length, `${edition} ${kind} ids are unique`);
      for (const x of list) assert.ok(x.id && x.name, `${edition} ${kind} entry without id or name`);
    }
  }
  assert.match(fs.readFileSync(path.join(srd, 'SOURCE.md'), 'utf8'), /commit `[0-9a-f]{40}`/);
});

test('entries have what the sheets and the GM screen use', () => {
  for (const edition of ['2014', '2024']) {
    for (const s of load(edition, 'spells')) {
      assert.ok(Number.isInteger(s.level) && s.level >= 0 && s.level <= 9, s.name);
      assert.ok(s.text.length > 10, `${s.name} has its text`);
      if (s.save) assert.ok(['str', 'dex', 'con', 'int', 'wis', 'cha'].includes(s.save), s.name);
    }
    for (const m of load(edition, 'monsters')) {
      assert.ok(m.hp > 0 && m.ac > 0, m.name);
      for (const k of ['str', 'dex', 'con', 'int', 'wis', 'cha']) assert.ok(m.abilities[k] >= 1 && m.abilities[k] <= 30, `${m.name} ${k}`);
      assert.ok(m.cr !== '' && m.cr != null, m.name);
      for (const key of ['traits', 'actions', 'bonusActions', 'reactions', 'legendary']) assert.ok(Array.isArray(m[key]), `${m.name} ${key}`);
    }
  }
  // Spot checks against the books' numbers.
  const fireball = (e) => load(e, 'spells').find(s => s.name === 'Fireball');
  for (const e of ['2014', '2024']) {
    assert.equal(fireball(e).level, 3); assert.equal(fireball(e).damage, '8d6'); assert.equal(fireball(e).save, 'dex');
  }
  const goblin = load('2014', 'monsters').find(m => m.name === 'Goblin');
  assert.deepEqual([goblin.ac, goblin.hp, goblin.hpFormula, goblin.cr], [15, 7, '2d6', '1/4']);
  const longsword = load('2024', 'equipment').find(x => x.name === 'Longsword');
  assert.deepEqual([longsword.damage, longsword.versatile, longsword.mastery, longsword.category], ['1d8', '1d10', 'Sap', 'Martial Melee Weapons']);
  const dagger = load('2014', 'equipment').find(x => x.name === 'Dagger');
  assert.deepEqual([dagger.range, dagger.finesse], ['20/60 ft.', true]);
});

test('every dice string in the reference rolls', async () => {
  const { rollDice } = await dice();
  let n = 0;
  const check = (expr, what) => { if (!expr) return; n++; assert.doesNotThrow(() => rollDice(expr), `${what}: ${expr}`); };
  for (const edition of ['2014', '2024']) {
    for (const s of load(edition, 'spells')) { check(s.damage, s.name); check(s.heal, s.name); }
    for (const m of load(edition, 'monsters')) {
      check(m.hpFormula, `${m.name} HP`);
      for (const a of [...m.actions, ...m.bonusActions, ...m.reactions, ...m.legendary]) {
        check(a.damage, `${m.name} ${a.name}`);
        if (a.attack !== '' && a.attack != null) assert.ok(Number.isInteger(a.attack), `${m.name} ${a.name} attack`);
      }
    }
    for (const e of load(edition, 'equipment')) { check(e.damage, e.name); check(e.versatile, e.name); }
  }
  assert.ok(n > 1000, `checked ${n}`);
});

test('the reference is not precached by the service worker', () => {
  const src = fs.readFileSync(path.resolve(__dirname, '../client/scripts/inject-sw-assets.mjs'), 'utf8');
  assert.match(src, /startsWith\('src\/srd\/'\)/);
});
